/// <summary>
/// CB220_PlannerCodes Update buyer group on matching item coverage records contract
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(
        classStr(METReqItemTableBuyerGroupUpdUIBuilder),
        SysOperationDataContractProcessingMode::CreateSeparateUIBuilderForEachContract)
]
class METReqItemTableBuyerGroupUpdContract
{
    VendAccount         vendAccount;
    InventSiteId        inventSiteId;
    InventLocationId    inventLocationId;    

}

Method.Source:
    /// <summary>
    /// Vendor account parameter
    /// </summary>
    /// <param name = "_vendAccount">Vendor account</param>
    /// <returns>Vendor account</returns>
    [DataMember, SysOperationDisplayOrder('1')]
    public VendAccount parmVendAccount(VendAccount _vendAccount = vendAccount)
    {
        vendAccount = _vendAccount;

        return vendAccount;
    }

    /// <summary>
    /// Site parameter
    /// </summary>
    /// <param name = "_inventSiteId">Site</param>
    /// <returns>Site</returns>
    [DataMember, SysOperationDisplayOrder('2')]
    public InventSiteId parmInventSiteId(InventSiteId _inventSiteId = inventSiteId)
    {
        inventSiteId = _inventSiteId;

        return inventSiteId;
    }

    /// <summary>
    /// Warehouse parameter
    /// </summary>
    /// <param name = "_inventLocationId">Warehouse</param>
    /// <returns>Warehouse</returns>
    [DataMember, SysOperationDisplayOrder('3')]
    public InventLocationId parmInventLocationId(InventLocationId _inventLocationId = inventLocationId)
    {
        inventLocationId = _inventLocationId;

        return inventLocationId;
    }
